Hi, this solutions will not work (and it is not working on my tests). RC for this issue is that NXP code use io id as ID for pin. 
For example for pin iomuxc_gpio_ad_b1_06_gpio1_io22 we have to set PIN to 22. Proposed fix colony cover configuration part, but it not cover points like: zephyr/include/zephyr/drivers/gpio.h: 1269
```
static inline int gpio_pin_set_raw(const struct device *port, gpio_pin_t pin,
				   int value)
{
	__unused const struct gpio_driver_config *const cfg =
		(const struct gpio_driver_config *)port->config;
	int ret;

	__ASSERT((cfg->port_pin_mask & (gpio_port_pins_t)BIT(pin)) != 0U,
		 "Unsupported pin");

	if (value != 0)	{
		ret = gpio_port_set_bits_raw(port, (gpio_port_pins_t)BIT(pin));
	} else {
		ret = gpio_port_clear_bits_raw(port, (gpio_port_pins_t)BIT(pin));
	}

	return ret;
}
```
at this point pin = 16 (for  iomuxc_gpio_ad_b1_06_gpio1_io22)  witch is equal index in gpio1 from zephyr/dts/arm/nxp/nxp_rt1024.dtsi

Hi @asarbs, this sample code toggles GPIO1, pin 28 (GPIO_AD_B1_12) for me on the RT1024 EVK. Can you verify this works for you?

```
#include <zephyr/kernel.h>
#include <zephyr/drivers/gpio.h>

void main(void)
{
	int ret;

	const struct device *gpio1 = DEVICE_DT_GET(DT_NODELABEL(gpio1));
	ret = gpio_pin_configure(gpio1, 28, GPIO_OUTPUT);
	if (ret) {
		printk("Error: could not configure GPIO1 pin 28\n");
	}
	while (1) {
		ret = gpio_pin_toggle(gpio1, 28);
		if (ret) {
			printk("Error: could not toggle GPIO1 pin 28\n");
		}
		k_msleep(1000);
	}
}
```

